-- Create index "task_tenant_id_assignee_id" to table: "tasks"
CREATE INDEX "task_tenant_id_assignee_id" ON "tasks" ("tenant_id", "assignee_id");
-- Create index "task_tenant_id_parent_id" to table: "tasks"
CREATE INDEX "task_tenant_id_parent_id" ON "tasks" ("tenant_id", "parent_id");
-- Modify "outbox_events" table
ALTER TABLE "outbox_events" ALTER COLUMN "status" SET DEFAULT 'PENDING', ADD COLUMN "published_at" timestamptz NULL, ADD COLUMN "error_message" text NULL;
-- Create index "tender_tenant_id_number" to table: "tenders"
CREATE UNIQUE INDEX "tender_tenant_id_number" ON "tenders" ("tenant_id", "number");
-- Create "document_sequences" table
CREATE TABLE "document_sequences" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "kind" character varying NOT NULL, "last_value" bigint NOT NULL DEFAULT 0, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "documentsequence_tenant_id_kind" to table: "document_sequences"
CREATE UNIQUE INDEX "documentsequence_tenant_id_kind" ON "document_sequences" ("tenant_id", "kind");
-- Create "permissions" table
CREATE TABLE "permissions" ("id" uuid NOT NULL, "permission_code" character varying NOT NULL, "name" character varying NOT NULL, "module" character varying NOT NULL, "action" character varying NOT NULL, "resource" character varying NULL, "description" text NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "permission_module_action" to table: "permissions"
CREATE INDEX "permission_module_action" ON "permissions" ("module", "action");
-- Create index "permissions_permission_code_key" to table: "permissions"
CREATE UNIQUE INDEX "permissions_permission_code_key" ON "permissions" ("permission_code");
-- Create "roles" table
CREATE TABLE "roles" ("id" uuid NOT NULL, "tenant_id" uuid NULL, "role_code" character varying NOT NULL, "name" character varying NOT NULL, "description" text NULL, "is_system_role" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "role_role_code" to table: "roles"
CREATE UNIQUE INDEX "role_role_code" ON "roles" ("role_code") WHERE (tenant_id IS NULL);
-- Create index "role_tenant_id" to table: "roles"
CREATE INDEX "role_tenant_id" ON "roles" ("tenant_id");
-- Create index "role_tenant_id_role_code" to table: "roles"
CREATE UNIQUE INDEX "role_tenant_id_role_code" ON "roles" ("tenant_id", "role_code") WHERE (tenant_id IS NOT NULL);
-- Create "role_permissions" table
CREATE TABLE "role_permissions" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "role_id" uuid NOT NULL, "permission_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "role_permissions_permissions_permission" FOREIGN KEY ("permission_id") REFERENCES "permissions" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "role_permissions_roles_role" FOREIGN KEY ("role_id") REFERENCES "roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "rolepermission_permission_id" to table: "role_permissions"
CREATE INDEX "rolepermission_permission_id" ON "role_permissions" ("permission_id");
-- Create index "rolepermission_role_id_permission_id" to table: "role_permissions"
CREATE UNIQUE INDEX "rolepermission_role_id_permission_id" ON "role_permissions" ("role_id", "permission_id");
-- Create "projects_users" table
CREATE TABLE "projects_users" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "auth_service_user_id" uuid NOT NULL, "email" character varying NULL, "name" character varying NULL, "status" character varying NOT NULL DEFAULT 'active', "sync_status" character varying NOT NULL DEFAULT 'synced', "last_sync_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "projectsuser_auth_service_user_id" to table: "projects_users"
CREATE INDEX "projectsuser_auth_service_user_id" ON "projects_users" ("auth_service_user_id");
-- Create index "projectsuser_tenant_id_auth_service_user_id" to table: "projects_users"
CREATE UNIQUE INDEX "projectsuser_tenant_id_auth_service_user_id" ON "projects_users" ("tenant_id", "auth_service_user_id");
-- Create "user_role_assignments" table
CREATE TABLE "user_role_assignments" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "assigned_by" uuid NOT NULL, "assigned_at" timestamptz NOT NULL, "expires_at" timestamptz NULL, "user_id" uuid NOT NULL, "role_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "user_role_assignments_projects_users_user" FOREIGN KEY ("user_id") REFERENCES "projects_users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "user_role_assignments_roles_role" FOREIGN KEY ("role_id") REFERENCES "roles" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "userroleassignment_role_id" to table: "user_role_assignments"
CREATE INDEX "userroleassignment_role_id" ON "user_role_assignments" ("role_id");
-- Create index "userroleassignment_tenant_id_user_id_role_id" to table: "user_role_assignments"
CREATE UNIQUE INDEX "userroleassignment_tenant_id_user_id_role_id" ON "user_role_assignments" ("tenant_id", "user_id", "role_id");
-- The global "tenders_number_key" goes after the per-tenant index exists (migrate.DropLegacyIndexes).
DROP INDEX IF EXISTS "tenders_number_key";
